#define main legacy_coupled_entry
#include "test_coupled.c"
#undef main
static uint8_t uart_wire[512];static uint16_t uart_words[512];static unsigned wire_count,status_reads,mutation;static int ready;
static bs_flow uart_hal(void *p,bs_model *b,const bs_request *r,bs_result *out){(void)p;CHECK(b==&m.startup);out->known=UINT32_MAX;out->value=0;
    if(r->operation==BS_MMIO_READ){if(r->address==0x40004400){CHECK(r->width==16);status_reads++;out->value=ready?64u:0u;}return BS_RETURNED;}
    if(r->operation==BS_MMIO_WRITE){if(r->address==0x40004404){CHECK(r->width==16);CHECK(wire_count<sizeof(uart_wire));if(wire_count<sizeof(uart_wire)){uart_words[wire_count]=(uint16_t)r->value;uart_wire[wire_count++]=(uint8_t)r->value;}if(mutation==1&&wire_count==6)m.ota.reply_data[0]^=1;if(mutation==2&&wire_count==6)m.ota.reply_mask[1]=0;if(mutation==3&&wire_count==3)put(A(0x999b),7,1);}return BS_RETURNED;}
    return BS_HALT;
}
static void uart_fresh(void){bs_backend b;fresh(TC_BOOT);memset(&b,0,sizeof(b));b.hal=uart_hal;ta_set_startup_backend(&m,&b);wire_count=status_reads=mutation=0;ready=1;memset(uart_wire,0,sizeof(uart_wire));memset(uart_words,0,sizeof(uart_words));}
static uint8_t expected_i(void){unsigned i;uint8_t sum=(uint8_t)('I'+15+2+4);for(i=0;i<12;i++)sum=(uint8_t)(sum+uid[i]);return sum;}
static void completed_native_body(void){uint8_t w[16];size_t n;group("core UART I uses real BS polling/writes while scalar uart_ready is NO");uart_fresh();m.ota.uart_ready=TC_NO;put(A(0x408b),0x77,1);n=frame(w,'I',NULL,0);CHECK(ta_receive_uart(&m,w,n,1)==n);CHECK(m.halted==0&&m.ota.uart_session==1);CHECK(wire_count==21&&status_reads==42);CHECK(uart_wire[0]==85&&uart_wire[1]==127&&uart_wire[2]=='I');CHECK(uart_wire[3]==0&&uart_wire[4]==15&&uart_wire[5]==uid[0]);CHECK(uart_wire[20]==expected_i()&&get(A(0x999b),1)==uart_wire[20]);CHECK(get(A(0x408b),1)==0x77);}
static void blocked_poll_prefix(void){uint8_t w[16];size_t n;group("first UART poll failure keeps checksum reset prefix, parser callback and challenge session unfinished");uart_fresh();put(A(0x408c),1,1);m.startup.poll_budget=3;ready=0;n=frame(w,'I',NULL,0);CHECK(ta_receive_uart(&m,w,n,1)==n-1);CHECK(m.halted==1&&m.ota.interpretation_halted==1);CHECK(wire_count==0&&status_reads==3);CHECK(get(A(0x999b),1)==0&&m.memory.known[0x999b]==255);CHECK(get(A(0x999d),1)==6&&get(A(0x999c),1)==0);CHECK(m.startup.boundary_va==0x23c6&&m.startup.boundary_address==0x40004400);}
static void live_payload_reread(void){uint8_t w[16];size_t n;group("native UART checksum rereads abstract payload after MMIO write rather than cached frame byte");uart_fresh();mutation=1;n=frame(w,'I',NULL,0);CHECK(ta_receive_uart(&m,w,n,1)==n);CHECK(wire_count==21&&uart_wire[5]==uid[0]);CHECK(uart_wire[20]==(uint8_t)(expected_i()-1));CHECK(get(A(0x999b),1)==uart_wire[20]);CHECK(m.ota.reply_data[0]==(uint8_t)(uid[0]^1));}
static void unknown_live_payload(void){uint8_t w[16];size_t n;group("unknown next payload after first write halts full body before caller session update");uart_fresh();mutation=2;n=frame(w,'I',NULL,0);CHECK(ta_receive_uart(&m,w,n,1)==n-1);CHECK(wire_count==6&&status_reads==12);CHECK(m.halted==1&&m.ota.uart_session==0);CHECK(get(A(0x999d),1)==6);CHECK(m.startup.boundary_va==0x245e);CHECK(get(A(0x999b),1)==(uint8_t)('I'+15+uid[0]));}
static void live_checksum_alias(void){uint8_t w[16];size_t n;group("HAL checksum alias writes survive command staging export and native wrapper reread");uart_fresh();mutation=3;n=frame(w,'I',NULL,0);CHECK(ta_receive_uart(&m,w,n,1)==n);CHECK(wire_count==21&&uart_wire[20]==(uint8_t)(expected_i()+7));CHECK(get(A(0x999b),1)==uart_wire[20]);CHECK(m.ota.uart.sum==uart_wire[20]&&m.ota.uart.sum_mask==255);}
static void abstract_view_width_and_resume(void){uint8_t data[257],masks[257],sum;unsigned i;bs_uart_view view;group("abstract UART view keeps full count and raw command low16, plus explicit diagnostic reset");uart_fresh();for(i=0;i<257;i++){data[i]=(uint8_t)i;masks[i]=255;}view.data=data;view.known=masks;view.available=257;CHECK(bs_uart_reply_view(&m.startup,0x1234,&view,257)==BS_RETURNED);CHECK(wire_count==263&&status_reads==526&&uart_words[2]==0x1234);sum=(uint8_t)(0x34+1);for(i=0;i<257;i++)sum=(uint8_t)(sum+data[i]);CHECK(uart_wire[4]==1&&uart_wire[261]==0&&uart_wire[262]==sum);uart_fresh();masks[1]=0;CHECK(bs_uart_reply_view(&m.startup,'Q',&view,2)==BS_HALT);CHECK(wire_count==6&&m.startup.boundary_is_abstract==1&&m.startup.boundary_offset==1);bs_resume(&m.startup);CHECK(m.startup.boundary_is_abstract==0&&m.startup.boundary_offset==0);wire_count=status_reads=0;view.data=view.known=NULL;view.available=0;CHECK(bs_uart_reply_view(&m.startup,'A',&view,0)==BS_RETURNED);CHECK(wire_count==6&&uart_wire[5]=='A');uart_fresh();CHECK(bs_uart_reply_view(&m.startup,'Q',NULL,1)==BS_HALT);CHECK(wire_count==5&&m.startup.boundary_is_abstract==1&&m.startup.boundary_offset==0);}
int main(int argc,char **argv){FILE *f;unsigned i;if(argc!=3)return 2;f=fopen(argv[1],"rb");if(!f||fread(runtime,1,sizeof(runtime),f)!=sizeof(runtime)){if(f)fclose(f);return 2;}fclose(f);f=fopen(argv[2],"rb");if(!f||fread(boot,1,sizeof(boot),f)!=sizeof(boot)){if(f)fclose(f);return 2;}fclose(f);for(i=0;i<14;i++){uid[i]=(uint8_t)(17+i);known[i]=255;}uid[12]=uid[0];uid[13]=uid[1];completed_native_body();blocked_poll_prefix();live_payload_reread();unknown_live_payload();live_checksum_alias();abstract_view_width_and_resume();printf("UART_BRIDGE_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
